import { IHikingWeatherDTO } from '../@types/DTO/hikingWeather.dto.types';
import { IHikingWeather } from '../@types/hikingWeather.types';

const mapWeather = (
  backData: IHikingWeatherDTO['forecast']['weather'][number],
): IHikingWeather['forecast']['weather'][number] => {
  return {
    id: backData.id,
    description: backData.description,
    icon: backData.icon,
    main: backData.main,
  };
};

export const mapHikingWeatherToFront = (backData: IHikingWeatherDTO): IHikingWeather => {
  return {
    created_at: new Date(backData.created_at),
    date: new Date(backData.date),
    forecast: {
      clouds: backData.forecast.clouds,
      deg: backData.forecast.deg,
      dt: backData.forecast.dt,
      feels_like: {
        day: backData.forecast.feels_like.day,
        eve: backData.forecast.feels_like.eve,
        morn: backData.forecast.feels_like.morn,
        night: backData.forecast.feels_like.night,
      },
      gust: backData.forecast.gust,
      humidity: backData.forecast.humidity,
      pop: backData.forecast.pop,
      pressure: backData.forecast.pressure,
      rain: backData.forecast.rain,
      speed: backData.forecast.speed,
      sunrise: backData.forecast.sunrise,
      sunset: backData.forecast.sunset,
      temp: {
        day: backData.forecast.temp.day,
        eve: backData.forecast.temp.eve,
        max: backData.forecast.temp.max,
        min: backData.forecast.temp.min,
        morn: backData.forecast.temp.morn,
        night: backData.forecast.temp.night,
      },
      weather: backData.forecast.weather.map(mapWeather),
    },
    lat: +backData.lat,
    lon: +backData.lon,
    name: backData.name,
  };
};
