import { get } from '@helpers/httpClient';

import { mapHikingWeatherToFront } from '../@mappers/hikingWeather.mapper';
import { IHikingWeatherDTO } from '../@types/DTO/hikingWeather.dto.types';

export const getHikingWeather = async (id_hiking: number) => {
  const res = await get<IHikingWeatherDTO[]>('/ajax/hiking/weather.php', { id_hiking });
  return res.map(mapHikingWeatherToFront);
};
